//! Vectors for WF's verifier-reachable public data, generated by
//! `scripts/cpp_vectors/wf_vectors.cpp`.

use std::collections::HashMap;

use fp_core::chain::public::PublicBytes;
use fp_core::code::code::Code;
use fp_core::field::ext::{E, F};
use fp_core::iop::context::OracleNotice;
use fp_core::iop::iopp::{IoppChoice, IoppStage};
use fp_core::iop::lkp::LkpKeys;
use fp_core::iop::mask::{receipt_for_a_test, SendAccess};
use fp_core::iop::message::Writer;
use fp_core::iop::relation::{Codes, OracleShape, Part, Row, Statement};
use fp_core::iop::tensor::Tensor;
use fp_core::iop::wf::{
    wf_covers_all_rows, wf_fault, wf_first_fold, wf_index_mask_entries, wf_index_masks,
    wf_layout, wf_lookup_fault, wf_lookups, wf_message, wf_own_masks, wf_part_fault,
    wf_pending_row, wf_planes_at, wf_public_fault, wf_rows_batched, wf_run_fault, wf_start_check,
    wf_weights_on_rows, WfLookup, WfMatrix, WfPart, WfPublic, WfRun,
};

const VECTORS: &str = include_str!("../../fixtures/wf_vectors.txt");

fn fields(line: &str) -> HashMap<&str, &str> {
    line.split_whitespace()
        .filter_map(|t| t.split_once('='))
        .map(|(k, v)| (k, v))
        .collect()
}

fn f(s: &str) -> F {
    F(u64::from_str_radix(s, 16).unwrap())
}

fn e(s: &str) -> E {
    let p: Vec<&str> = s.trim_start_matches('=').split(',').collect();
    assert_eq!(p.len(), 3, "E {}", s);
    E([f(p[0]), f(p[1]), f(p[2])])
}

fn eseq(s: &str) -> Vec<E> {
    s.trim_start_matches('=').split(';').map(e).collect()
}

fn rest<'a>(line: &'a str, tag: &str) -> &'a str {
    assert!(line.starts_with(tag), "line {} does not begin with {}", line, tag);
    line[tag.len()..].trim()
}

fn list(s: &str) -> Vec<&str> {
    if s == "-" {
        Vec::new()
    } else {
        s.split(',').collect()
    }
}

/// A list of structures (`keys`, `tables`, `padding`): entries are separated by `|`.
fn plist(s: &str) -> Vec<&str> {
    if s == "-" {
        Vec::new()
    } else {
        s.split('|').collect()
    }
}

fn u32s(s: &str) -> Vec<u32> {
    list(s).iter().map(|x| x.parse().unwrap()).collect()
}

fn run(first_place: u64, first_row: u64, places: u64, stride: u64) -> WfRun {
    WfRun { first_place, first_row, places, stride }
}

fn part(log_places: u32, runs: Vec<WfRun>) -> WfPart {
    WfPart { log_places, runs }
}

fn lookup(
    name: &str,
    d: u32,
    mu: u32,
    live: u32,
    digit_weight: Vec<F>,
    offset: F,
    padding_key: F,
    parts: Vec<WfPart>,
    first_bound: Vec<u32>,
) -> WfLookup {
    WfLookup {
        name: name.into(),
        d,
        mu,
        live,
        digit_weight,
        offset,
        padding_key,
        parts,
        first_bound,
    }
}

fn notice(name: &str, code: u32, main_rows: usize, mask_rows: usize, mask_code: u32, answers: u32, leaf: u32) -> OracleNotice {
    let mut shape = OracleShape::default();
    shape.name = name.into();
    shape.code = code;
    shape.main_rows = main_rows;
    shape.main_deg = 1;
    shape.mask_rows = mask_rows;
    shape.mask_code = mask_code;
    shape.answers = answers;
    OracleNotice { shape, leaf_class: leaf }
}

fn minimal_codes() -> Codes {
    Codes {
        base: vec![Code { log_n: 7, ell: 4, r: 2 }],
        mask: vec![Code { log_n: 5, ell: 32, r: 0 }, Code { log_n: 7, ell: 128, r: 0 }],
    }
}

fn minimal_matrix() -> WfMatrix {
    WfMatrix { k_col: 1, rows: 2 }
}

fn minimal_public() -> WfPublic {
    WfPublic {
        lookups: vec![lookup(
            "bytes",
            1,
            2,
            3,
            vec![F(1)],
            F(0),
            F(0),
            vec![part(1, vec![run(0, 0, 2, 0)])],
            vec![],
        )],
        message: notice("ranges-msg", 0, 2, 2, 0, 1, 7),
        message_id: 1,
        stages: vec![
            IoppStage { code: 0, mask_code: 0, k: 1, h: 1 },
            IoppStage { code: 0, mask_code: 1, k: 0, h: 0 },
        ],
        choice: IoppChoice { masks_ride: false },
    }
}

fn rich_codes() -> Codes {
    Codes { base: vec![Code { log_n: 5, ell: 32, r: 1 }], mask: vec![Code { log_n: 5, ell: 32, r: 0 }] }
}

fn rich_matrix() -> WfMatrix {
    WfMatrix { k_col: 2, rows: 8 }
}

fn rich_public() -> WfPublic {
    WfPublic {
        lookups: vec![
            lookup(
                "lo",
                2,
                2,
                0,
                vec![F(1)],
                F(5),
                F(3),
                vec![part(2, vec![run(0, 0, 3, 0)]), part(1, vec![run(0, 3, 1, 0)])],
                vec![0],
            ),
            lookup("li", 3, 2, 0, vec![F(2), F(3)], F(1), F(2), vec![part(1, vec![run(0, 2, 1, 1)])], vec![0]),
            lookup("lz", 2, 2, 3, vec![F(4)], F(0), F(1), vec![part(1, vec![run(0, 0, 2, 0)])], vec![]),
        ],
        message: notice("ranges-msg", 0, 2, 2, 0, 2, 7),
        message_id: 3,
        stages: vec![
            IoppStage { code: 0, mask_code: 0, k: 1, h: 1 },
            IoppStage { code: 0, mask_code: 1, k: 0, h: 0 },
        ],
        choice: IoppChoice { masks_ride: true },
    }
}

fn check_tensor(t: &Tensor, kv: &HashMap<&str, &str>) {
    assert_eq!(t.scalar, e(kv["scalar"]));
    assert_eq!(t.vars(), kv["vars"].parse::<u32>().unwrap());
    assert_eq!(t.has_dense(), kv["dense"] == "1");
    let dv: Vec<u32> = if kv["dvars"] == "-" {
        Vec::new()
    } else {
        kv["dvars"].split(',').map(|x| x.parse().unwrap()).collect()
    };
    assert_eq!(t.dense_vars, dv);
    assert_eq!(t.first, kv["first"].parse::<u64>().unwrap());
    let want: Option<usize> = if kv["len"] == "-" { None } else { Some(kv["len"].parse().unwrap()) };
    assert_eq!(t.values.as_ref().map(|v| v.len()), want);
}

fn check_layout(lines: &mut std::str::Lines<'_>, x: &WfPublic, ell: u64) {
    let kv = fields(lines.next().unwrap());
    assert_eq!(kv["ell"].parse::<u64>().unwrap(), ell);
    let blocks = wf_layout(x, ell);
    assert_eq!(blocks.len(), kv["n"].parse::<usize>().unwrap());
    for (i, b) in blocks.iter().enumerate() {
        let kv = fields(lines.next().unwrap());
        assert_eq!(kv["i"].parse::<usize>().unwrap(), i);
        assert_eq!(b.lookup, kv["lookup"].parse::<usize>().unwrap());
        assert_eq!(
            b.planes,
            (kv["first"].parse::<u32>().unwrap(), kv["log"].parse::<u32>().unwrap())
        );
        assert_eq!(b.bits, kv["bits"].parse::<u32>().unwrap());
        assert_eq!(b.row, kv["row"].parse::<u64>().unwrap());
        assert_eq!(b.first_place, kv["at"].parse::<u64>().unwrap());
    }
}

fn check_weights_case(lines: &mut std::str::Lines<'_>, tag: &str) {
    let kv = fields(lines.next().unwrap());
    assert_eq!(kv["case"], tag);
    let k_row = kv["k_row"].parse::<u32>().unwrap();
    let first_row = kv["first_row"].parse::<u64>().unwrap();
    let first = kv["first"].parse::<u64>().unwrap();
    let count = kv["count"].parse::<u64>().unwrap();
    let values_len = kv["values"].parse::<usize>().unwrap();
    let n = kv["n"].parse::<usize>().unwrap();
    assert_eq!(k_row, kv["k_row"].parse::<u32>().unwrap());
    let mut body: Vec<String> = Vec::new();
    for i in 0..n {
        let line = lines.next().unwrap();
        assert_eq!(fields(line)["tensor"].parse::<usize>().unwrap(), i);
        body.push(line.to_string());
        for _ in 0..(1usize << k_row) {
            body.push(lines.next().unwrap().to_string());
        }
    }
    let values: Vec<E> = (0..values_len)
        .map(|i| E([F(1000 + i as u64), F(2000 + i as u64), F(3000 + i as u64)]))
        .collect();
    let shared = std::rc::Rc::new(values);
    let mut g = Vec::new();
    wf_weights_on_rows(k_row, first_row, &shared, first, count, E([F(7), F(8), F(9)]), &mut g);
    assert_eq!(g.len(), n);
    let mut body = body.into_iter();
    for (i, t) in g.iter().enumerate() {
        let line = body.next().unwrap();
        let kv = fields(&line);
        assert_eq!(kv["tensor"].parse::<usize>().unwrap(), i);
        check_tensor(t, &kv);
        for j in 0..(1u64 << k_row) {
            let line = body.next().unwrap();
            let kv = fields(&line);
            assert_eq!(kv["case"], tag);
            assert_eq!(kv["tensor"].parse::<usize>().unwrap(), i);
            assert_eq!(kv["j"].parse::<u64>().unwrap(), j);
            assert_eq!(t.at(j), e(kv["v"]));
        }
    }
    assert!(body.next().is_none());
}

fn good_part() -> WfPart {
    part(1, vec![run(0, 0, 2, 0)])
}

fn fault_value(name: &str) -> Option<&'static str> {
    let codes = minimal_codes();
    let m = minimal_matrix();
    let x = minimal_public();
    match name {
        "run_no_places" => wf_run_fault(&run(0, 0, 0, 0)),
        "part_too_many_places" => wf_part_fault(&WfPart { log_places: 41, runs: vec![run(0, 0, 1, 0)] }),
        "part_overlap" => wf_part_fault(&part(2, vec![run(0, 0, 2, 0), run(1, 0, 2, 0)])),
        "part_beyond" => wf_part_fault(&part(2, vec![run(3, 0, 2, 0)])),
        "part_empty" => wf_part_fault(&WfPart { log_places: 1, runs: vec![] }),
        "lookup_planes" => wf_lookup_fault(&lookup(
            "bad",
            1,
            0,
            0,
            vec![F(1)],
            F(0),
            F(0),
            vec![good_part()],
            vec![],
        )),
        "lookup_no_digit" => wf_lookup_fault(&lookup(
            "bad",
            1,
            2,
            0,
            vec![],
            F(0),
            F(0),
            vec![good_part()],
            vec![],
        )),
        "lookup_zero_weight" => wf_lookup_fault(&lookup(
            "bad",
            1,
            2,
            0,
            vec![F(0)],
            F(0),
            F(0),
            vec![good_part()],
            vec![],
        )),
        "lookup_padding" => wf_lookup_fault(&lookup(
            "bad",
            2,
            2,
            0,
            vec![F(1)],
            F(0),
            F(4),
            vec![good_part()],
            vec![],
        )),
        "lookup_bound_twice" => wf_lookup_fault(&lookup(
            "bad",
            1,
            2,
            0,
            vec![F(1)],
            F(0),
            F(0),
            vec![good_part()],
            vec![0, 0],
        )),
        "lookup_stride_one_digit" => wf_lookup_fault(&lookup(
            "bad",
            1,
            2,
            0,
            vec![F(1)],
            F(0),
            F(0),
            vec![part(1, vec![run(0, 0, 2, 1)])],
            vec![],
        )),
        "lookup_no_stride" => wf_lookup_fault(&lookup(
            "bad",
            1,
            2,
            0,
            vec![F(1), F(2)],
            F(0),
            F(0),
            vec![part(1, vec![run(0, 0, 2, 0)])],
            vec![],
        )),
        "public_no_lookup" => {
            let mut y = x.clone();
            y.lookups.clear();
            wf_public_fault(&y)
        }
        "public_no_main" => {
            let mut y = x.clone();
            y.message.shape.main_rows = 0;
            wf_public_fault(&y)
        }
        "wf_ok" => wf_fault(&codes, &x, &m),
        "wf_no_rows" => wf_fault(&codes, &x, &WfMatrix { k_col: 1, rows: 0 }),
        "wf_run_beyond" => wf_fault(&codes, &x, &WfMatrix { k_col: 1, rows: 1 }),
        "wf_part_keys" => wf_fault(&codes, &x, &WfMatrix { k_col: 2, rows: 2 }),
        "wf_uncovered" => wf_fault(&codes, &x, &WfMatrix { k_col: 1, rows: 3 }),
        "wf_bad_code" => {
            let mut y = x.clone();
            y.message.shape.code = 5;
            wf_fault(&codes, &y, &m)
        }
        "wf_block_long" => {
            let mut y = x.clone();
            y.message.shape.code = 1;
            let mut c = codes.clone();
            c.base.push(Code { log_n: 6, ell: 2, r: 0 });
            wf_fault(&c, &y, &m)
        }
        "wf_main_rows" => {
            let mut y = x.clone();
            y.message.shape.main_rows = 1;
            wf_fault(&codes, &y, &m)
        }
        "wf_mask_room" => {
            let mut y = x.clone();
            y.message.shape.mask_code = 2;
            let mut c = codes.clone();
            c.mask.push(Code { log_n: 5, ell: 8, r: 0 });
            wf_fault(&c, &y, &m)
        }
        "wf_stage_code" => {
            let mut y = x.clone();
            y.stages[0].code = 1;
            wf_fault(&codes, &y, &m)
        }
        "wf_iopp" => {
            let mut y = x.clone();
            y.stages[0].k = 0;
            y.stages[0].h = 0;
            wf_fault(&codes, &y, &m)
        }
        other => panic!("unknown fault {}", other),
    }
}

#[test]
fn wf_vectors_match_the_cpp_reference() {
    let mut lines = VECTORS.lines();
    let rich = rich_public();
    let rich_m = rich_matrix();
    let rich_c = rich_codes();
    let min = minimal_public();
    let min_m = minimal_matrix();

    // The public bytes of the rich case.
    let line = lines.next().unwrap();
    let mut w = Writer::default();
    rich.public_bytes(&mut w);
    let hex: String = w.bytes().iter().map(|b| format!("{:02x}", b)).collect();
    assert_eq!(hex, rest(line, "PUBLIC_BYTES"));

    // wf_lookups.
    let kv = fields(lines.next().unwrap());
    let lookups = wf_lookups(&rich, &rich_m);
    assert_eq!(lookups.len(), kv["n"].parse::<usize>().unwrap());
    for (i, p) in lookups.iter().enumerate() {
        let kv = fields(lines.next().unwrap());
        assert_eq!(kv["i"].parse::<usize>().unwrap(), i);
        assert_eq!(p.parts, u32s(kv["parts"]));
        assert_eq!(p.d, kv["d"].parse::<u32>().unwrap());
        assert_eq!(p.mu, kv["mu"].parse::<u32>().unwrap());
        assert_eq!(p.live, kv["live"].parse::<u32>().unwrap());
        assert_eq!(p.h, kv["h"].parse::<u32>().unwrap());
        assert_eq!(p.g, kv["g"].parse::<u32>().unwrap());
        assert_eq!(p.shifted, kv["shifted"] == "1");
        assert_eq!(p.read_from, u32s(kv["read_from"]));
        let keys = plist(kv["keys"]);
        assert_eq!(p.keys.len(), keys.len());
        for (k, s) in p.keys.iter().zip(keys) {
            let q: Vec<&str> = s.split(':').collect();
            assert_eq!(k.first, q[0].parse::<u64>().unwrap());
            assert_eq!(k.log_trees, q[1].parse::<u32>().unwrap());
            assert_eq!(k.function, q[2].parse::<i32>().unwrap());
            assert_eq!(k.padding_row, q[3].parse::<u64>().unwrap());
        }
        let tables = plist(kv["tables"]);
        assert_eq!(p.tables.len(), tables.len());
        for (t, s) in p.tables.iter().zip(tables) {
            let q: Vec<&str> = s.split(':').collect();
            assert_eq!(t.first, q[0].parse::<u64>().unwrap());
            assert_eq!(t.log_rows, q[1].parse::<u32>().unwrap());
            assert_eq!(t.function, q[2].parse::<u32>().unwrap());
            assert_eq!(t.rows.len(), q[3].parse::<usize>().unwrap());
        }
        let padding = plist(kv["padding"]);
        assert_eq!(p.padding.len(), padding.len());
        for (pad, s) in p.padding.iter().zip(padding) {
            let q: Vec<&str> = s.split(':').collect();
            assert_eq!(pad.part, q[0].parse::<u32>().unwrap());
            assert_eq!(pad.first, q[1].parse::<u64>().unwrap());
            assert_eq!(pad.log_step, q[2].parse::<u32>().unwrap());
            assert_eq!(pad.length, q[3].parse::<u64>().unwrap());
            assert_eq!(pad.row, q[4].parse::<u64>().unwrap());
        }
        assert_eq!(p.last_key_level_order, u32s(kv["order"]));
    }

    // The derived sizes.
    let kv = fields(lines.next().unwrap());
    assert_eq!(wf_index_masks(&rich, &rich_m), kv["index_masks"].parse::<usize>().unwrap());
    assert_eq!(
        wf_index_mask_entries(&rich, &rich_m),
        kv["index_mask_entries"].parse::<usize>().unwrap()
    );
    assert_eq!(wf_own_masks(&rich, &rich_m), kv["own_masks"].parse::<usize>().unwrap());
    assert_eq!(wf_rows_batched(&rich, &rich_m), kv["rows_batched"].parse::<u64>().unwrap());

    // The layout.
    check_layout(&mut lines, &rich, 32);
    check_layout(&mut lines, &rich, 16);

    // Coverage.
    let kv = fields(lines.next().unwrap());
    assert_eq!(rich_m.rows, kv["rows"].parse::<u64>().unwrap());
    for i in 0..rich.lookups.len() {
        assert_eq!(
            wf_covers_all_rows(&rich, i, &rich_m),
            kv[format!("i{}", i).as_str()] == "1"
        );
    }
    let kv = fields(lines.next().unwrap());
    assert_eq!(min_m.rows, kv["rows"].parse::<u64>().unwrap());
    assert_eq!(wf_covers_all_rows(&min, 0, &min_m), kv["i0"] == "1");

    // The plane callback.
    for i in 0..rich.lookups.len() {
        let kv = fields(lines.next().unwrap());
        let vars = kv["vars"].parse::<u32>().unwrap();
        let log_ell = kv["log_ell"].parse::<u32>().unwrap();
        let row_bits = kv["row_bits"].parse::<u32>().unwrap();
        let n = kv["n"].parse::<u64>().unwrap();
        let line = lines.next().unwrap();
        let z = eseq(line.split_whitespace().nth(2).unwrap());
        assert_eq!(z.len(), vars as usize);
        let mut row = Row::plain("planes");
        let planes = wf_planes_at(&rich, &rich_c, i);
        planes(&mut row, Tensor::eq(&z, vars, E::one()));
        for j in 0..n {
            let kv = fields(lines.next().unwrap());
            assert_eq!(kv["i"].parse::<usize>().unwrap(), i);
            assert_eq!(kv["j"].parse::<u64>().unwrap(), j);
            assert_eq!(row.coefficient(rich.message_id, Part::Main, j), e(kv["v"]));
        }
        assert_eq!(1u64 << (log_ell + row_bits), n);
    }

    // The row weights.
    check_weights_case(&mut lines, "A");
    check_weights_case(&mut lines, "B");
    check_weights_case(&mut lines, "C");

    // A pending row.
    let kv = fields(lines.next().unwrap());
    let k_row = kv["k_row"].parse::<u32>().unwrap();
    let n = kv["n"].parse::<u64>().unwrap();
    let tensors_n = kv["tensors"].parse::<usize>().unwrap();
    assert_eq!(k_row, rich_m.k_row());
    assert_eq!(n, 1u64 << k_row);
    let covered = e(rest(lines.next().unwrap(), "PCOVERED"));
    let point = eseq(rest(lines.next().unwrap(), "PPOINT"));
    let target = e(rest(lines.next().unwrap(), "PTARGET"));
    let psi = eseq(rest(lines.next().unwrap(), "PPSI"));
    let row_target = e(rest(lines.next().unwrap(), "PROWTARGET"));
    let masks_n = rest(lines.next().unwrap(), "PMASKS").parse::<usize>().unwrap();
    let mut claim = LkpKeys::default();
    claim.point = point.clone();
    claim.target = target;
    claim.weights.entries.push((0, covered));
    let row = wf_pending_row(&rich_m, &rich.lookups[0], &rich.lookups[0].parts[0], claim);
    assert_eq!(row.psi, psi);
    assert_eq!(row.target, row_target);
    assert_eq!(row.masks.len(), masks_n);
    assert_eq!(row.g.len(), tensors_n);
    for (i, t) in row.g.iter().enumerate() {
        let kv = fields(lines.next().unwrap());
        assert_eq!(kv["tensor"].parse::<usize>().unwrap(), i);
        check_tensor(t, &kv);
        for j in 0..n {
            let kv = fields(lines.next().unwrap());
            assert_eq!(kv["tensor"].parse::<usize>().unwrap(), i);
            assert_eq!(kv["j"].parse::<u64>().unwrap(), j);
            assert_eq!(t.at(j), e(kv["v"]));
        }
    }

    // The first fold and the prover message's notices.
    let kv = fields(lines.next().unwrap());
    let fold = wf_first_fold(&rich);
    assert_eq!(fold.code, kv["code"].parse().unwrap());
    assert_eq!(fold.mask_code, kv["mask_code"].parse().unwrap());
    assert_eq!(fold.layout.k, kv["k"].parse().unwrap());
    assert_eq!(fold.layout.h, kv["h"].parse().unwrap());
    assert_eq!(fold.mask_leaf_class, kv["leaf"].parse().unwrap());
    assert_eq!(fold.keep_folded_coefficients, kv["keep"] == "1");
    assert_eq!(fold.folded_coefficients_alone, kv["alone"] == "1");
    assert_eq!(fold.target_from_the_rounds, kv["rounds"] == "1");
    let kv = fields(lines.next().unwrap());
    let msg = wf_message(&rich);
    assert_eq!(msg.len(), kv["n"].parse::<usize>().unwrap());
    for (i, m) in msg.iter().enumerate() {
        let kv = fields(lines.next().unwrap());
        assert_eq!(kv["i"].parse::<usize>().unwrap(), i);
        assert_eq!(m.shape.name.replace(' ', "_"), kv["name"]);
        assert_eq!(m.shape.code, kv["code"].parse().unwrap());
        assert_eq!(m.shape.main_rows, kv["main"].parse().unwrap());
        assert_eq!(m.shape.main_deg, kv["deg"].parse().unwrap());
        assert_eq!(m.shape.mask_rows, kv["mask"].parse().unwrap());
        assert_eq!(m.shape.mask_code, kv["mask_code"].parse().unwrap());
        assert_eq!(m.shape.answers, kv["answers"].parse().unwrap());
        assert_eq!(m.leaf_class, kv["leaf"].parse().unwrap());
    }

    // The faults.
    while let Some(line) = lines.next() {
        let (name, want) = line.split_once(" value=").unwrap();
        let name = name.strip_prefix("FAULT name=").unwrap();
        assert_eq!(fault_value(name).unwrap_or("none"), want, "fault {}", name);
    }
}

#[test]
fn wf_start_check_accepts_a_sampled_index_mask_message() {
    let mut st = Statement::new(minimal_codes());
    let mut shape = OracleShape::default();
    shape.name = "index masks".into();
    shape.main_rows = 0;
    shape.mask_rows = 2;
    shape.mask_code = 0;
    shape.answers = 1;
    let o = st.sent(shape);
    st.sampled(
        &SendAccess,
        o,
        vec![Row::plain("a sample")],
        Vec::new(),
        receipt_for_a_test(o, 0, 63, 2, 1),
    );
    wf_start_check(&st, &minimal_public(), &minimal_matrix(), o);
}

#[test]
#[should_panic(expected = "WF: the index-mask message is a sampled message")]
fn wf_start_check_refuses_an_unsampled_index_mask_message() {
    let mut st = Statement::new(minimal_codes());
    let mut shape = OracleShape::default();
    shape.name = "index masks".into();
    shape.main_rows = 0;
    shape.mask_rows = 2;
    shape.mask_code = 0;
    shape.answers = 1;
    let o = st.sent(shape);
    wf_start_check(&st, &minimal_public(), &minimal_matrix(), o);
}
